-- Imported authors are attribution, never accounts or memberships.
CREATE TABLE source_people (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), provider TEXT NOT NULL, source_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT, avatar_url TEXT, UNIQUE(workspace_id,id), UNIQUE(workspace_id,provider,source_id));
ALTER TABLE issues ADD COLUMN creator_source_id TEXT REFERENCES source_people(id);
ALTER TABLE issues ADD COLUMN assignee_source_id TEXT REFERENCES source_people(id);
ALTER TABLE projects ADD COLUMN lead_source_id TEXT REFERENCES source_people(id);
ALTER TABLE comments ADD COLUMN author_source_id TEXT REFERENCES source_people(id);
ALTER TABLE activity ADD COLUMN actor_source_id TEXT REFERENCES source_people(id);
CREATE TABLE initiatives (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','completed','canceled')), owner_id TEXT, owner_source_id TEXT REFERENCES source_people(id), target_date TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE initiative_projects (workspace_id TEXT NOT NULL, initiative_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(initiative_id,project_id), FOREIGN KEY(workspace_id,initiative_id) REFERENCES initiatives(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE documents (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', project_id TEXT, initiative_id TEXT, creator_id TEXT NOT NULL, creator_source_id TEXT REFERENCES source_people(id), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,creator_id) REFERENCES memberships(workspace_id,user_id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,initiative_id) REFERENCES initiatives(workspace_id,id));
CREATE TABLE linear_imports (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, source_workspace_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'staging' CHECK(status IN ('staging','planned','completed')), manifest TEXT NOT NULL, plan_hash TEXT, result TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,created_by) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE linear_import_records (workspace_id TEXT NOT NULL, import_id TEXT NOT NULL, collection TEXT NOT NULL, source_id TEXT NOT NULL, payload TEXT NOT NULL, payload_hash TEXT NOT NULL, PRIMARY KEY(import_id,collection,source_id), FOREIGN KEY(workspace_id,import_id) REFERENCES linear_imports(workspace_id,id));
CREATE TABLE linear_source_map (workspace_id TEXT NOT NULL REFERENCES workspaces(id), source_workspace_id TEXT NOT NULL, collection TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, payload_hash TEXT NOT NULL, import_id TEXT NOT NULL, PRIMARY KEY(workspace_id,source_workspace_id,collection,source_id), FOREIGN KEY(workspace_id,import_id) REFERENCES linear_imports(workspace_id,id));
CREATE INDEX imported_record_lookup ON linear_import_records(workspace_id,collection,source_id);
CREATE INDEX documents_workspace ON documents(workspace_id,updated_at,id);
CREATE INDEX initiatives_workspace ON initiatives(workspace_id,updated_at,id);
ALTER TABLE statuses ADD COLUMN source_type TEXT;
